CREATE TABLE IF NOT EXISTS login_protection (id integer PRIMARY KEY, config_ciphertext text NOT NULL) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS login_guards (source_hash varchar(64) PRIMARY KEY, source_ip varchar(45) NOT NULL, blocked_until datetime(6), updated_at datetime(6) NOT NULL, INDEX login_guard_expiry(blocked_until), INDEX login_guard_age(updated_at)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS login_failures (id varchar(36) PRIMARY KEY, source_hash varchar(64) NOT NULL, occurred_at datetime(6) NOT NULL, INDEX login_failure_source(source_hash,occurred_at), INDEX login_failure_time(occurred_at)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS captcha_used (token_hash varchar(64) PRIMARY KEY, expires_at datetime(6) NOT NULL, INDEX captcha_expiry(expires_at)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
